css:
.ops-layout { max-width: 860px; margin: 0 auto; padding: 40px 24px 60px; }
.ops-main { width: 100%; }
.ops-toc { display: none; }
.ops-toc-title { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.1em; color: var(--text-muted); margin-bottom: 12px; padding-left: 12px; }
.ops-toc ul { list-style: none; padding: 0; margin: 0; }
.ops-toc li { margin: 0; }
.ops-toc a { display: block; padding: 5px 12px; font-size: 0.8rem; color: var(--text-muted); text-decoration: none; border-left: 2px solid transparent; transition: all 0.2s; line-height: 1.4; }
.ops-toc a:hover { color: var(--text); border-left-color: var(--border); }
.ops-toc a.active { color: var(--accent); border-left-color: var(--accent); font-weight: 600; }
 .ops-main { max-width: 100%; } }

h1 { font-family: var(--font-display); font-size: 2.2rem; font-weight: 800; letter-spacing: -0.03em; background: var(--gradient); -webkit-background-clip: text; background-clip: text; color: transparent; margin-bottom: 6px; line-height: 1.2; }
.ops-subtitle { color: var(--text-muted); font-size: 1.05rem; font-weight: 300; margin-bottom: 12px; }
.ops-series-badge { display: inline-flex; align-items: center; gap: 6px; padding: 4px 12px; background: rgba(37,99,235,0.08); color: var(--accent); border-radius: 20px; font-size: 0.75rem; font-weight: 600; letter-spacing: 0.02em; margin-bottom: 32px; }
[data-theme='dark'] .ops-series-badge { background: rgba(96,165,250,0.12); }

.ops-section { margin-top: 48px; scroll-margin-top: 20px; }
.ops-section-title { display: flex; align-items: center; gap: 10px; font-family: var(--font-display); font-size: 1.35rem; font-weight: 700; color: var(--text); margin-bottom: 16px; padding-bottom: 10px; border-bottom: 2px solid var(--border); letter-spacing: -0.01em; }
.ops-section-title svg { flex-shrink: 0; color: var(--accent); }
.ops-section p { font-size: 0.92rem; color: var(--text-secondary); line-height: 1.65; margin-bottom: 16px; }

.ops-callout { display: flex; gap: 12px; padding: 14px 18px; border-radius: 10px; margin: 16px 0; border-left: 4px solid; font-size: 0.88rem; line-height: 1.6; }
.ops-callout-icon { flex-shrink: 0; width: 20px; height: 20px; margin-top: 1px; }
.ops-callout-body { flex: 1; }
.ops-callout-body strong { display: block; margin-bottom: 2px; }
.ops-callout.info { background: rgba(37,99,235,0.06); border-left-color: var(--accent); color: var(--text); }
.ops-callout.info .ops-callout-icon { color: var(--accent); }
.ops-callout.warning { background: var(--warning-light); border-left-color: var(--warning); color: var(--text); }
.ops-callout.warning .ops-callout-icon { color: var(--warning); }
.ops-callout.danger { background: var(--error-light); border-left-color: var(--error); color: var(--text); }
.ops-callout.danger .ops-callout-icon { color: var(--error); }
.ops-callout.tip { background: var(--success-light); border-left-color: var(--success); color: var(--text); }
.ops-callout.tip .ops-callout-icon { color: var(--success); }

.ops-cmd { position: relative; background: var(--code-bg-dark); border: 1px solid var(--code-border-dark); border-radius: 8px; margin: 12px 0; overflow: hidden; }
.ops-cmd-label { display: block; padding: 6px 14px; font-size: 0.68rem; font-weight: 600; text-transform: uppercase; letter-spacing: 0.08em; color: var(--code-header-text); background: var(--code-header-bg); border-bottom: 1px solid var(--code-border-dark); }
.ops-cmd code { display: block; padding: 14px 50px 14px 16px; font-family: var(--font-mono); font-size: 0.82rem; line-height: 1.6; color: #e2e8f0; white-space: pre-wrap; word-break: break-all; }
.ops-cmd-copy { position: absolute; top: auto; bottom: 8px; right: 8px; width: 30px; height: 30px; border-radius: 6px; background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.1); color: #94a3b8; cursor: pointer; display: flex; align-items: center; justify-content: center; transition: all 0.15s; }
.ops-cmd-copy:hover { background: rgba(255,255,255,0.12); color: #e2e8f0; }
.ops-cmd-copy.copied { background: rgba(34,197,94,0.15); border-color: rgba(34,197,94,0.3); color: #4ade80; }
.ops-cmd-copy svg { width: 14px; height: 14px; }

.ops-table-wrap { overflow-x: auto; margin: 16px 0; border-radius: 10px; border: 1px solid var(--border); }
.ops-table { width: 100%; border-collapse: collapse; font-size: 0.85rem; }
.ops-table th { text-align: left; padding: 10px 14px; font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); background: var(--surface2); border-bottom: 2px solid var(--border); white-space: nowrap; }
.ops-table td { padding: 10px 14px; color: var(--text); border-bottom: 1px solid var(--border); vertical-align: top; }
.ops-table tr:last-child td { border-bottom: none; }
.ops-table tbody tr:nth-child(even) td { background: var(--surface2); }
.ops-table tbody tr:hover td { background: var(--surface-hover); }
.ops-table code { font-family: var(--font-mono); font-size: 0.78rem; background: rgba(37,99,235,0.08); color: var(--accent); padding: 1px 6px; border-radius: 4px; }

.ops-series-nav { margin-top: 48px; padding-top: 24px; border-top: 2px solid var(--border); }
.ops-series-nav-title { font-family: var(--font-display); font-size: 1.1rem; font-weight: 600; color: var(--text); margin-bottom: 14px; }
.ops-series-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 12px; }
@media (max-width: 700px) { .ops-series-grid { grid-template-columns: 1fr; } }
.ops-series-link { display: flex; align-items: center; gap: 12px; padding: 14px 16px; background: var(--surface); border: 1px solid var(--border); border-radius: 10px; text-decoration: none; color: var(--text); transition: all 0.2s; cursor: pointer; }
.ops-series-link:hover { border-color: var(--accent); box-shadow: 0 4px 16px var(--accent-glow); transform: translateY(-1px); }
.ops-series-link-icon { width: 36px; height: 36px; border-radius: 8px; background: var(--bg-tertiary); display: flex; align-items: center; justify-content: center; flex-shrink: 0; color: var(--accent); }
.ops-series-link-icon svg { width: 18px; height: 18px; }
.ops-series-link-body h4 { font-size: 0.88rem; font-weight: 600; margin: 0 0 2px; }
.ops-series-link-body p { font-size: 0.75rem; color: var(--text-muted); margin: 0; line-height: 1.35; }

/* ── Flow diagrams ── */
.ops-flow { display: flex; align-items: center; justify-content: center; gap: 0; flex-wrap: wrap; padding: 24px 20px; background: var(--surface); border: 1px solid var(--border); border-radius: 14px; margin: 20px 0; overflow-x: auto; }
.ops-flow-step { display: flex; flex-direction: column; align-items: center; gap: 6px; min-width: 80px; max-width: 110px; text-align: center; flex-shrink: 0; }
.ops-flow-num { width: 32px; height: 32px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 0.75rem; font-weight: 700; font-family: var(--font-mono); color: #fff; flex-shrink: 0; }
.ops-flow-num.green { background: var(--success); }
.ops-flow-num.red { background: var(--error); }
.ops-flow-num.blue { background: var(--accent); }
.ops-flow-num.orange { background: #f97316; }
.ops-flow-num.purple { background: #8b5cf6; }
.ops-flow-label { font-size: 0.72rem; font-weight: 600; color: var(--text); line-height: 1.3; }
.ops-flow-arrow { color: var(--text-muted); font-size: 1.1rem; flex-shrink: 0; padding: 0 2px; margin-top: -10px; }
@media (max-width: 700px) { .ops-flow { flex-direction: column; gap: 4px; padding: 16px 12px; } .ops-flow-step { flex-direction: row; max-width: 100%; min-width: 0; gap: 10px; } .ops-flow-arrow { transform: rotate(90deg); margin-top: 0; } .ops-flow-label { text-align: left; } }

/* ── Pipeline diagrams (horizontal lanes) ── */
.ops-pipeline { background: var(--surface); border: 1px solid var(--border); border-radius: 14px; padding: 24px 20px; margin: 20px 0; overflow-x: auto; }
.ops-pipeline-title { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: var(--text-muted); margin-bottom: 16px; text-align: center; }
.ops-lane { display: flex; align-items: center; gap: 0; margin: 10px 0; flex-wrap: nowrap; justify-content: center; }
.ops-lane-label { font-size: 0.68rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; color: var(--text-muted); min-width: 70px; flex-shrink: 0; }
.ops-pipe-node { display: inline-flex; align-items: center; gap: 5px; padding: 6px 12px; border-radius: 8px; font-size: 0.78rem; font-weight: 600; font-family: var(--font-mono); border: 1px solid var(--border); background: var(--surface2); color: var(--text); white-space: nowrap; flex-shrink: 0; }
.ops-pipe-node.accent { background: var(--accent); color: #fff; border-color: var(--accent); }
.ops-pipe-node.monitoring { border-color: var(--accent2); color: var(--accent2); }
.ops-pipe-node.db { border-color: var(--pgvector); color: var(--pgvector); }
.ops-pipe-node.cache { border-color: var(--celery); color: var(--celery); }
.ops-pipe-node.storage { border-color: #eab308; color: #eab308; }
.ops-pipe-node.hub { background: var(--accent2); color: #fff; border-color: var(--accent2); font-weight: 700; }
.ops-pipe-arrow { color: var(--text-muted); font-size: 1rem; flex-shrink: 0; padding: 0 4px; }
@media (max-width: 700px) { .ops-lane { flex-wrap: wrap; justify-content: flex-start; gap: 4px; } .ops-lane-label { min-width: 100%; margin-bottom: 4px; } .ops-pipe-node { font-size: 0.72rem; padding: 4px 8px; } }

/* ── Zone diagrams (nested boxes) ── */
.ops-zones { margin: 20px 0; }
.ops-zone { border-radius: 12px; padding: 16px; margin: 0; position: relative; }
.ops-zone-label { display: inline-flex; align-items: center; gap: 6px; font-size: 0.72rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.06em; margin-bottom: 10px; padding: 3px 10px; border-radius: 6px; }
.ops-zone.internet { background: rgba(239,68,68,0.06); border: 2px dashed rgba(239,68,68,0.3); }
.ops-zone.internet .ops-zone-label { background: rgba(239,68,68,0.1); color: #ef4444; }
.ops-zone.dmz { background: rgba(249,115,22,0.06); border: 2px solid rgba(249,115,22,0.3); }
.ops-zone.dmz .ops-zone-label { background: rgba(249,115,22,0.1); color: #f97316; }
.ops-zone.internal { background: rgba(34,197,94,0.06); border: 2px solid rgba(34,197,94,0.3); }
.ops-zone.internal .ops-zone-label { background: rgba(34,197,94,0.1); color: #22c55e; }
.ops-zone.data { background: rgba(37,99,235,0.06); border: 2px solid rgba(37,99,235,0.3); }
.ops-zone.data .ops-zone-label { background: rgba(37,99,235,0.1); color: var(--accent); }
.ops-zone-services { display: flex; flex-wrap: wrap; gap: 8px; margin-top: 8px; }
.ops-zone-svc { display: inline-flex; align-items: center; gap: 4px; padding: 5px 10px; background: var(--surface); border: 1px solid var(--border); border-radius: 6px; font-size: 0.75rem; font-weight: 600; font-family: var(--font-mono); color: var(--text); }
.ops-zone-arrow { text-align: center; color: var(--text-muted); font-size: 1.2rem; margin: 0; }
@media (max-width: 700px) { .ops-zone { padding: 10px 8px; } .ops-zone-svc { font-size: 0.7rem; padding: 4px 7px; } }

/* ── Decision tree ── */
.ops-dtree { background: var(--surface); border: 1px solid var(--border); border-radius: 14px; padding: 24px 20px; margin: 20px 0; text-align: center; overflow-x: auto; }
.ops-dtree-row { display: flex; align-items: flex-start; justify-content: center; gap: 16px; margin: 6px 0; flex-wrap: wrap; }
.ops-dtree-node { display: inline-flex; align-items: center; gap: 5px; padding: 8px 14px; border-radius: 8px; font-size: 0.8rem; font-weight: 600; background: var(--surface2); border: 1px solid var(--border); color: var(--text); }
.ops-dtree-node.start { background: var(--accent); color: #fff; border-color: var(--accent); }
.ops-dtree-node.decision { background: var(--surface2); border: 2px solid var(--warning); color: var(--text); transform: rotate(0deg); clip-path: polygon(50% 0%, 100% 50%, 50% 100%, 0% 50%); padding: 20px 28px; font-size: 0.72rem; }
.ops-dtree-node.action { background: rgba(34,197,94,0.08); border-color: var(--success); color: var(--text); }
.ops-dtree-node.escalate { background: rgba(239,68,68,0.08); border-color: var(--error); color: var(--text); }
.ops-dtree-arrow { color: var(--text-muted); font-size: 1rem; }
.ops-dtree-branch { display: flex; flex-direction: column; align-items: center; gap: 6px; }
.ops-dtree-branch-label { font-size: 0.68rem; font-weight: 700; color: var(--success); text-transform: uppercase; }
.ops-dtree-branch-label.no { color: var(--error); }
@media (max-width: 700px) { .ops-dtree-row { flex-direction: column; align-items: center; gap: 8px; } .ops-dtree-node.decision { padding: 14px 20px; } .ops-dtree-fork { flex-direction: column; align-items: center; gap: 12px; } .ops-dtree-fork::before { display: none; } .ops-dtree-branch { width: 100%; align-items: center; } }

/* ── Decision tree v2 ── */
.ops-dtree { background: var(--surface); border: 1px solid var(--border); border-radius: 14px; padding: 28px 20px; margin: 20px 0; display: flex; flex-direction: column; align-items: center; gap: 0; overflow-x: auto; }
.ops-dtree-node { display: inline-flex; align-items: center; padding: 10px 20px; border-radius: 10px; font-size: 0.82rem; font-weight: 600; border: 2px solid var(--border); background: var(--surface2); color: var(--text); white-space: nowrap; }
.ops-dtree-node.start { background: var(--accent); color: #fff; border-color: var(--accent); }
.ops-dtree-node.question { border-color: var(--warning); background: rgba(234,179,8,0.06); }
.ops-dtree-node.yes { border-color: var(--success); background: rgba(34,197,94,0.06); }
.ops-dtree-node.no { border-color: var(--error); background: rgba(239,68,68,0.06); }
.ops-dtree-connector { width: 2px; height: 28px; background: var(--border); }
.ops-dtree-fork { display: flex; align-items: flex-start; gap: 32px; position: relative; }
.ops-dtree-fork::before { content: ''; position: absolute; top: 0; left: 0; right: 0; height: 2px; background: var(--border); }
.ops-dtree-branch { display: flex; flex-direction: column; align-items: center; gap: 0; min-width: 120px; }
.ops-dtree-branch-line { width: 2px; height: 22px; background: var(--border); }
.ops-dtree-branch-tag { font-size: 0.7rem; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em; padding: 2px 8px; border-radius: 4px; margin: 4px 0; }
.ops-dtree-branch-tag.yes { color: var(--success); background: rgba(34,197,94,0.08); }
.ops-dtree-branch-tag.no { color: var(--error); background: rgba(239,68,68,0.08); }
@media (max-width: 600px) { .ops-dtree-node { font-size: 0.75rem; padding: 7px 12px; } }
@media (max-width: 600px) { .ops-layout { padding: 24px 14px 40px; } }
